           using System;
using static System.Console;
namespace lab1
{
    class Nodo1
    {
        public int Valor;
        public Nodo1 Siguiente;
        public Nodo1(int valor)
        {
            Valor = valor;
            Siguiente = null;
        }

    }
}
using System;
using static System.Console;


namespace lab1
{
    class ListaSimple1
    {
        public Nodo1 Cabeza;
        public ListaSimple1()
        {
            Cabeza = null;
        }
        public void Agregar(int valor)
        {
            Nodo1 nuevo = new Nodo1(valor);
            if (Cabeza == null)
            {
                Cabeza = nuevo;
            }
            else
            {
                Nodo1 actual = Cabeza;
                while(actual.Siguiente != null)
                {
                    actual = actual.Siguiente;
                }
                actual.Siguiente = nuevo;
            }
        }
        public void MovermaximoalFinal()
        {
            if (Cabeza == null || Cabeza.Siguiente == null) return;
            Nodo1 nodoAnteriorMaximo = null;
            Nodo1 nodoMaximo = Cabeza;
            Nodo1 nodoAnterior = null;
            Nodo1 actual = Cabeza;
            while (actual != null)   //BUSMAR EL NODO MAX
            {
                if(actual.Valor > nodoMaximo.Valor)
                {
                    nodoMaximo = actual;
                    nodoAnteriorMaximo = nodoAnterior;
                }
                nodoAnterior = actual;
                actual = actual.Siguiente;

            }
            if (nodoMaximo.Siguiente == null) return;  //SI YA SE ENCUENTRA AL FINAL, NO SE HACE NADA

            if (nodoAnteriorMaximo != null) //PARA PODER QUITAR EL NODO MAXIMO
            {
                nodoAnteriorMaximo.Siguiente = nodoMaximo.Siguiente;
            }
            else
            {
                Cabeza = nodoMaximo.Siguiente;
            }
                nodoAnterior.Siguiente = nodoMaximo;   //PARA PONER AL FINAL
            nodoMaximo.Siguiente = null;
        }
        public void OrdenarAscendente()
        {
            if (Cabeza == null || Cabeza.Siguiente == null) return;
            bool cambiado;
            do
            {
                cambiado = false;
                Nodo1 actual = Cabeza;
                while (actual.Siguiente != null)
                {
                    if (actual.Valor > actual.Siguiente.Valor)
                    {
                        int temp = actual.Valor;
                        actual.Valor = actual.Siguiente.Valor;
                        actual.Siguiente.Valor = temp;
                        cambiado = true;
                    }
                    actual = actual.Siguiente;
                }
            } while (cambiado);
        }
        public void Imprimir()
        {
            Nodo1 actual = Cabeza;
            while (actual != null)
            {
                WriteLine(actual.Valor + "--->");
                actual = actual.Siguiente;
            }
            WriteLine("null");
        }

    }
}
sing System;
using static System.Console;
namespace lab1
{
    internal class Program
    {
        static void Main()
        {
            //NODO 1 Y LISTA SIMPLE 1
            ListaSimple1 lista = new ListaSimple1();
            lista.Agregar(3);
            lista.Agregar(8);
            lista.Agregar(10);
            lista.Agregar(25);
            lista.Agregar(15);
            lista.Agregar(5);
            WriteLine("EJERCICIO 1");
            WriteLine("La lista original es: ");
            lista.Imprimir();
            lista.MovermaximoalFinal();
            WriteLine("La lista despues de haber movido el maximo al final: ");
            lista.OrdenarAscendente();
            WriteLine("La lista ordenada en forma ascendente: ");
            lista.Imprimir();

        }
    }
}

            using System;
using static System.Console;

namespace lab1
{
    internal class Nodo2
    {
        public int Valor;
        public Nodo2 Siguiente;
        public Nodo2(int valor)
        { Valor = valor;
            Siguiente = null;
        }


    }
}
using System;
using static System.Console;

namespace lab1
{
    internal class ListaSimple2
    {
        public Nodo2 Cabeza;  

        public void Agregar(int valor)
        {
            Nodo2 nuevo = new Nodo2(valor);
            if (Cabeza == null)
            {
                Cabeza = nuevo; 
            }
            else
            {
                Nodo2 actual = Cabeza;
                while (actual.Siguiente != null)
                {
                    actual = actual.Siguiente;
                }
                actual.Siguiente = nuevo;
            }
        }
        public void EliminarDominados()
        {
            while (Cabeza != null && Cabeza.Siguiente != null && Cabeza.Valor < Cabeza.Siguiente.Valor) 
            {
                Cabeza = Cabeza.Siguiente;  
            }

            Nodo2 actual = Cabeza;  

            while (actual != null && actual.Siguiente != null)
            {
                if (actual.Siguiente.Siguiente != null && actual.Siguiente.Valor < actual.Siguiente.Siguiente.Valor) 
                {
                    actual.Siguiente = actual.Siguiente.Siguiente;
                }
                else
                {
                    actual = actual.Siguiente;
                }
            }
        }

        public void Imprimir()
        {
            Nodo2 actual = Cabeza;
            while (actual != null)
            {
               Write(actual.Valor + " , ");
                actual = actual.Siguiente;
            }
            WriteLine("null");
        }
    }
}
using System;
using static System.Console;
namespace lab1
{
    internal class Program
    {
        static void Main()
        {
            // EJERCICIO 2: ListaSimple2
            ListaSimple2 lista2 = new ListaSimple2();
            int[] valores = { 3, 8, 2, 9, 5, 4 };
            foreach (int v in valores) lista2.Agregar(v);
            WriteLine("\nEJERCICIO 2");
            WriteLine("\nLista original:");
            lista2.Imprimir();
            lista2.EliminarDominados();
            WriteLine("\nLista sin dominados:");
            lista2.Imprimir();
        }
    }
}

