        public Nodo3 Derecha;
        public Nodo3(string valor) { Valor = valor; }
    }
}

            using System;
using static System.Console;

namespace lab1
{
    internal class ListaDoble3
    {
        public Nodo3 Cabeza;
        public Nodo3 Cola;

        public void Agregar(string valor)
        {
            Nodo3 nuevo = new Nodo3(valor);
            if (Cabeza == null)
            {
                Cabeza = Cola = nuevo;
            }
            else
            {
                Cola.Derecha = nuevo;
                nuevo.Izquierda = Cola;
                Cola = nuevo;
            }
        }

        public void Intercambiar(int k)
        {
            Nodo3 desdeInicio = Cabeza;
            for (int i = 0; i < k; i++) desdeInicio = desdeInicio.Derecha;

            Nodo3 desdeFinal = Cola;
            for (int i = 0; i < k; i++) desdeFinal = desdeFinal.Izquierda;

            // Intercambiar valores
            string temporal = desdeInicio.Valor;
            desdeInicio.Valor = desdeFinal.Valor;
            desdeFinal.Valor = temporal;
        }

        public void Imprimir()
        {
            Nodo3 actual = Cabeza;
            while (actual != null)
            {
                Write(actual.Valor + " - ");
                actual = actual.Derecha;
            }

        }
    }
}
