        }

    }
}

            using System;
using static System.Console;

namespace lab1
{
    internal class Nodo4
    {
        public char Valor;
        public Nodo4 Izquierda;
        public Nodo4 Derecha;
        public Nodo4(char valor) { Valor = valor; }
    }
}
using System;
using static System.Console;

namespace lab1
{
    internal class ListaDoble4
    {
        public Nodo4 Cabeza;
        public Nodo4 Cola;

        public void Agregar(char valor)
        {
            Nodo4 nuevo = new Nodo4(valor);
            if (Cabeza == null)
            {
                Cabeza = Cola = nuevo;
            }
            else
            {
                Cola.Derecha = nuevo;
                nuevo.Izquierda = Cola;
                Cola = nuevo;
            }
        }

        public bool EsPalindromo()
        {
            Nodo4 inicio = Cabeza;
            Nodo4 fin = Cola;

            while (inicio != null && fin != null && inicio != fin && inicio.Izquierda != fin)
            {
                if (inicio.Valor != fin.Valor)
                    return false;
                inicio = inicio.Derecha;
                fin = fin.Izquierda;
            }
            return true;
        }
        public void Imprimir()
        {
            Nodo4 actual = Cabeza;
            while (actual != null)
            {
                Write(actual.Valor + " , ");
                actual = actual.Derecha;
            }

        }
    }
}
using System;
using static System.Console;
namespace lab1
{
    internal class Program
    {
        static void Main()
        {            // EJERCICIO 4: ListaDoble4
            ListaDoble4 lista4 = new ListaDoble4();
            char[] valores4 = { 'r', 'a', 'd', 'a', 'r' };
            //char[] valores4 = { 'r', 'a', 'd', 'x', 'r' };
            foreach (char c in valores4) lista4.Agregar(c);

            WriteLine("\nEJERCICIO 4");
            WriteLine("\nAnalizando si la siguiente secuencia de caracteres es un palíndromo:");
            lista4.Imprimir();
            bool esPalindromo = lista4.EsPalindromo();
            if (esPalindromo)
                WriteLine("\n¡Esta secuencia SI es un palíndromo!");
            else
                WriteLine("\nEsta secuencia NO es un palíndromo.");
        }

    }
}

