            using System;
using static System.Console;

namespace lab1
{
    internal class Nodo5Doble
    {
        public int Valor;
        public Nodo5Doble Izquierda;
        public Nodo5Doble Derecha;

        public Nodo5Doble(int valor)
        {
            Valor = valor;
            Izquierda = null;
            Derecha = null;
        }
    }
}
using System;
using static System.Console;

namespace lab1
{
internal class ListaSimple5
{
        public Nodo5 Cabeza;

        public void Agregar(int valor)
        {
            Nodo5 nuevo = new Nodo5(valor);
            if (Cabeza == null)
            {
                Cabeza = nuevo;
            }
            else
            {
                Nodo5 actual = Cabeza;
                while (actual.Siguiente != null)
                    actual = actual.Siguiente;
                actual.Siguiente = nuevo;
            }
        }

        public ListaDoble5 GenerarPromedios()
        {
            ListaDoble5 listaPromedios = new ListaDoble5();
            Nodo5 anterior = Cabeza;
            Nodo5 actual = Cabeza?.Siguiente;

            while (actual != null && actual.Siguiente != null)
            {
                Nodo5 siguiente = actual.Siguiente;
                if ((anterior.Valor + siguiente.Valor) / 2 == actual.Valor)
                {
                    listaPromedios.Agregar(actual.Valor);
                }
                anterior = actual;
                actual = siguiente;
            }
            return listaPromedios;
        }
    }

    internal class ListaDoble5
    {
        public Nodo5Doble Cabeza;
        public Nodo5Doble Cola;

        public void Agregar(int valor)
        {
            Nodo5Doble nuevo = new Nodo5Doble(valor);
            if (Cabeza == null)
            {
                Cabeza = Cola = nuevo;
            }
            else
            {
                Cola.Derecha = nuevo;
                nuevo.Izquierda = Cola;
                Cola = nuevo;
            }
        }

        public void Imprimir()
        {
            Nodo5Doble actual = Cabeza;
            while (actual != null)
            {
                Write(actual.Valor + " , ");
                actual = actual.Derecha;
            }
            WriteLine("null");
        }
    }

}
            using System;
using static System.Console;
namespace lab1
{
    internal class Program
    {
        static void Main()
        {            // EJERCICIO 5: ListaSimple5 y ListaDoble5
            ListaSimple5 lista5 = new ListaSimple5();
            int[] valores5 = { 1, 3, 5, 4, 3, 9 };
            foreach (int v in valores5) lista5.Agregar(v);
            WriteLine("\nEJERCICIO 5");
            WriteLine("\nLa lista original es:");
            foreach (int v in valores5) Write(v + " , ");
            ListaDoble5 promedios5 = lista5.GenerarPromedios();
            WriteLine("\nLista de los promedios es:");
            promedios5.Imprimir();
        }

    }
}
